<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\OAuth\MagicLink\Infrastructure\Driver\Rest;

use Psr\Http\Message\ResponseInterface;
use Psr\Http\Message\ServerRequestInterface;
use Civi\Lughauth\Features\OAuth\MagicLink\Application\Usecase\RequestMagicLink\RequestMagicLinkUsecase;

class MagicLinkRequestController
{
    public function __construct(
        private readonly RequestMagicLinkUsecase $usecase,
    ) {
    }

    public function request(ServerRequestInterface $request, ResponseInterface $response, array $args): ResponseInterface
    {
        $tenant = $args['tenant'];
        $body   = (array) ($request->getParsedBody() ?? []);

        $email       = (string) ($body['email'] ?? '');
        $clientId    = (string) ($body['client_id'] ?? '');
        $redirectUri = (string) ($body['redirect_uri'] ?? '');
        $scope       = (string) ($body['scope'] ?? 'openid email');
        $state       = ($body['state'] ?? null) !== null ? (string) $body['state'] : null;

        if ($email !== '' && $clientId !== '' && $redirectUri !== '') {
            $this->usecase->request(
                email: $email,
                clientId: $clientId,
                redirectUri: $redirectUri,
                tenantName: $tenant,
                scope: $scope,
                state: $state,
            );
        }

        // Always 202 — anti-enumeration: never reveal whether the email exists.
        return $response->withStatus(202);
    }
}
